import{_ as a,o as t,c as i,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"Ceph RGW Refactoring Meeting 2023-01-22","description":"","frontmatter":{"title":"Ceph RGW Refactoring Meeting 2023-01-22","date":"2023-01-22T00:00:00.000Z","updated":"2023-02-24T00:00:00.000Z","tags":["Ceph","RGW","Code Analysis","Security","Multi","Site Synchronization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-01-22.md","filePath":"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-01-22.md","lastUpdated":1780460162000}'),l={name:"posts/2023/Ceph_RGW_Refactoring_Meeting_2023-01-22.md"};function o(n,e,s,h,_,c){return t(),i("div",null,[...e[0]||(e[0]=[r('<p>会议纪要</p><h3 id="会议概述" tabindex="-1">会议概述 <a class="header-anchor" href="#会议概述" aria-label="Permalink to &quot;会议概述&quot;">​</a></h3><p>本次会议主要讨论了Ceph RGW的代码重构，包括静态代码分析、对象清单隐私性、多站点同步状态可视化以及可加载模块的变更等多个议题。</p><h4 id="_1-gsac-coverity-分析项目讨论" tabindex="-1">1. <strong>GSAC Coverity 分析项目讨论</strong> <a class="header-anchor" href="#_1-gsac-coverity-分析项目讨论" aria-label="Permalink to &quot;1. **GSAC Coverity 分析项目讨论**&quot;">​</a></h4><ul><li>讨论了使用Coverity静态代码分析工具的优缺点，包括其Web UI的局限性以及如何处理假阳性问题。</li><li>决定继续使用Coverity工具，并考虑使用代码注释管理假阳性问题。</li><li>行动计划：学生负责清理和修复Coverity问题，并使用代码注释标记假阳性。</li></ul><h4 id="_2-rgw对象清单-manifest-隐私性讨论" tabindex="-1">2. <strong>RGW对象清单(Manifest)隐私性讨论</strong> <a class="header-anchor" href="#_2-rgw对象清单-manifest-隐私性讨论" aria-label="Permalink to &quot;2. **RGW对象清单(Manifest)隐私性讨论**&quot;">​</a></h4><ul><li>讨论了将RGW对象清单完全隐藏在RADOS后端，以增强隐私性。</li><li>决定将对象清单类型隐藏在RADOS存储后端，使RGW应用无法解码。</li><li>行动计划：继续讨论和实施具体的隐私化措施。</li></ul><h4 id="_3-多站点同步状态可视化" tabindex="-1">3. <strong>多站点同步状态可视化</strong> <a class="header-anchor" href="#_3-多站点同步状态可视化" aria-label="Permalink to &quot;3. **多站点同步状态可视化**&quot;">​</a></h4><ul><li>讨论了将多站点同步状态信息导出并可视化在Prometheus中的可行性。</li><li>认为这是一个复杂问题，需要进一步研究和讨论。</li><li>行动计划：详细阅读相关跟踪问题，并考虑如何改进同步状态的可视化。</li></ul><h4 id="_4-可加载模块的变更讨论" tabindex="-1">4. <strong>可加载模块的变更讨论</strong> <a class="header-anchor" href="#_4-可加载模块的变更讨论" aria-label="Permalink to &quot;4. **可加载模块的变更讨论**&quot;">​</a></h4><ul><li>讨论了对可加载模块进行大规模变更的可行性，特别是将驱动程序改为唯一指针的影响。</li><li>决定将此变更作为独立任务处理，确保不影响其他开发工作。</li><li>行动计划：将此变更作为独立任务处理。</li></ul><h4 id="_5-其他事项" tabindex="-1">5. <strong>其他事项</strong> <a class="header-anchor" href="#_5-其他事项" aria-label="Permalink to &quot;5. **其他事项**&quot;">​</a></h4><ul><li>讨论了其他可能的改进和问题，包括同步状态的可视化等。</li><li>行动计划：继续在开发列表中讨论和跟进。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>本次会议涵盖了多个关键议题，并制定了相应的行动计划。会议强调了静态代码分析、对象清单隐私性和多站点同步状态可视化等关键问题，并提出了相应的解决方案。</p>',15)])])}const p=a(l,[["render",o]]);export{u as __pageData,p as default};
